// ../case-tool/src/utils/shortId.ts
var ALPHANUMERIC = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
var getRandomBytes = (n) => globalThis.crypto.getRandomValues(new Uint8Array(n));
function prefixedId(prefix, count = 6) {
  let result = prefix;
  const limit = 256 - 256 % ALPHANUMERIC.length;
  const bytes = getRandomBytes(count * 2);
  let i = 0;
  let byteIdx = 0;
  while (i < count) {
    if (byteIdx >= bytes.length)
      break;
    const b = bytes[byteIdx++];
    if (b < limit) {
      result += ALPHANUMERIC[b % ALPHANUMERIC.length];
      i++;
    }
  }
  return result;
}

// ../case-tool/src/utils/binding-builder.ts
function createBinding(propertyAttribute, defaultValue, resource, resourceKey) {
  return {
    id: prefixedId("b", 8),
    name: propertyAttribute,
    type: "string",
    resource,
    propertyAttribute,
    resourceKey,
    default: defaultValue
  };
}
function createTaskBindings(taskName, folderPath, taskType) {
  const resource = taskType === "action" ? "app" : "process";
  const resourceKey = `${folderPath}.${taskName}`;
  const nameBinding = createBinding("name", taskName, resource, resourceKey);
  const folderPathBinding = createBinding("folderPath", folderPath, resource, resourceKey);
  return [nameBinding, folderPathBinding];
}
function createConnectorBindings(connectorKey, connectionId, folderKey) {
  const connectionBinding = {
    id: prefixedId("b", 8),
    name: `${connectorKey} connection`,
    type: "string",
    resource: "Connection",
    propertyAttribute: "ConnectionId",
    resourceKey: connectionId,
    default: connectionId
  };
  const folderKeyBinding = folderKey ? {
    id: prefixedId("b", 8),
    name: "FolderKey",
    type: "string",
    resource: "Connection",
    propertyAttribute: "folderKey",
    resourceKey: connectionId,
    default: folderKey
  } : undefined;
  return [connectionBinding, folderKeyBinding];
}

export { prefixedId, createTaskBindings, createConnectorBindings };

